INSERT INTO "public"."announcements" ("id", "author_id", "title", "body", "is_global", "created_at") VALUES 
('c126c289-380f-4b5c-bf86-40786bb75e68', 'fffa07ae-27f0-4145-9c2b-5a332d446e0f', '公告功能正式上線通知 Notice: Announcement Feature Is Now Live', '為了更有效率地發布與 MATTA 相關的重要資訊，我們已新增「公告」功能，並自即日起正式上線。 To improve the efficiency of sharing important MATTA-related information, a new Announcement feature has been added AND is now officially available. 未來相關通知、重要訊息及更新內容將透過此功能發布，請各位務必定期查看並留意最新公告，以避免遺漏重要資訊。 Moving forward, relevant notices, important information, AND updates will be posted through this feature. Please make sure to check it regularly AND stay updated to avoid missing any important information. 感謝大家的配合。 Thank you for your cooperation. - MA Center -', true, '2026-08-24 02:55:15.889283+00')
